from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def level_order(root):
    """Return level-order traversal of binary tree."""
    if not root:
        return []
    result = []
    queue = deque([root])

    while queue:
        level_size = len(queue)  # number of nodes at current level
        current_level = []

        for _ in range(level_size):
            curr = queue.popleft()
            current_level.append(curr.val)

            if curr.left:
                queue.append(curr.left)
            if curr.right:
                queue.append(curr.right)

        result.append(current_level)  # finished processing this level

    return result
